Method.Source:
/// <summary>
/// CoC | Initializes the data source
/// </summary>
void init()
{
    next init();

    this.object(fieldNum(SalesLine, QtyOrdered)).allowEdit(false);
}

/// <summary>
/// CoC | Overrides the write method to automatically create a DSD position for the sales line
/// if the item is not the DSD calculation item.
/// </summary>
void write()
{
    /// Call the original write method
    next write();

    /// Create DSD position if necessary
    this.addDSDPosition(this.cursor());
}

/// <summary>
/// Creates a DSD position for the given sales line if the item and customer are eligible.
/// If a DSD position already exists, it is recalculated; otherwise, a new one is created.
/// </summary>
/// <param name="_currentSalesLine">The current SalesLine buffer.</param>
void addDSDPosition(SalesLine _currentSalesLine)
{
    InventQty qtyOrdered;
    ItemId itemId;
    ItemId defaultDSDItemId;
    ItemId itemIdMother;
    InventDimId inventDimId;
    InventSiteId inventSiteId;
    SalesLine salesLineDSD;
    InventTransIdBase inventTransId;
    InventTable inventTable;
    EcoResDistinctProductVariant distinctProductVariant;
    inventDim inventDim;
    EcoResItemConfigurationName configId;
    SalesTable currentSalesTable;
    int dsPos;

    inventTransId = _currentSalesLine.InventTransId;

    /// If there is no InventTransId or VariantId, exit the method
    if (!inventTransId || !_currentSalesLine.inventDim().configId)
    {
        return;
    }

    defaultDSDItemId = AVARUMDSDManager::getDefaultDSDItemId(true);

    /// If the item is not the DSD calculation item itself, exit the method
    if (_currentSalesLine.ItemId == defaultDSDItemId)
    {
        return;
    }

    /// Find existing DSD sales line related to the current sales line by InventTransId
    select firstonly forupdate salesLineDSD
        where salesLineDSD.AVARUMSalesLineRef == inventTransId;

    /// Find current sales table
    currentSalesTable = SalesTable::find(_currentSalesLine.SalesId);

    /// Get distinct product variant for the current sales line item
    distinctProductVariant = _currentSalesLine.distinctProductVariant_AVA();

    try
    {
        // Automatically create DSD position if the item is DSD-eligible and the customer is a DSD licensee
        if (!distinctProductVariant.AVARUMDSDUsage || !currentSalesTable.custTable_CustAccount().AVARUMDSDLicense)
        {
            if (salesLineDSD)
            {
                ttsbegin;
                salesLineDSD.delete();
                ttscommit;
            }
        }
        else
        {
            var inventTableDSD = InventTable::find(defaultDSDItemId);

            if (inventTableDSD)
            {
                itemId = _currentSalesLine.itemId;
                itemIdMother = _currentSalesLine.itemId;
                qtyOrdered = _currentSalesLine.QtyOrdered;
                configId = _currentSalesLine.inventDim().ConfigId;
                inventDimId = _currentSalesLine.InventDimId;
                inventSiteId = _currentSalesLine.inventDim().InventSiteId;

                ttsbegin;   

                dsPos = FormDataUtil::getRecordPosition(_currentSalesLine);

                if (!salesLineDSD.RecId)
                {                            
                    this.create();
                    salesLineDSD = this.cursor();                
                    salesLineDSD.initFromInventTable(inventTableDSD);
                    salesLineDSD.itemId = defaultDSDItemId;
                    salesLineDSD.itemIdChanged();      

                    InventMovement::bufferSetTransQtyUnit(salesLineDSD);

                    element.updateDesign(InventDimFormDesignUpdate::FieldChange);  
                    element.checkCreditNoteLine();

                    salesLineDSD.Name = strFmt("@AVARUM:DSDFor", itemId);
                    salesLineDSD.AVARUMDSDPos = NoYes::Yes;
                    salesLineDSD.AVARUMSalesLineRef = inventTransId;
                }

                inventDim = salesLineDSD.inventDim(true);
                inventDim.InventSiteId = inventDim.InventSiteId ? inventDim.InventSiteId : inventSiteId;
                inventDimId = InventDim::findOrCreate(inventDim).inventDimId;
                salesLineDSD.InventDimId = inventDimId;

                salesLineDSD.LineAmount = 0;
                salesLineDSD.SalesPrice = 0;
                salesLineDSD.SalesQty = qtyOrdered;
                salesLineDSD.QtyOrdered = qtyOrdered;    

                SalesLine::modifySalesQty(salesLineDSD, inventDim, true);                                         
                SalesPrice priceUnrounded=AVARUMDSDCalculationManager::calcPackingAmount(1, itemId, configId, salesLineDSD, itemIdMother);

                salesLineDSD.PriceUnit=10000;
                salesLineDSD.AVARUMPriceUnitID=_currentSalesLine.AVARUMPriceUnitID;
                salesLineDSD.SalesPrice = (salesLineDSD.SalesQty ? priceUnrounded / salesLineDSD.SalesQty : 0) * salesLineDSD.PriceUnit;
                Currency currency=Currency::find(salesLineDSD.CurrencyCode);
                salesLineDSD.SalesPrice=currency.amount_Instance(salesLineDSD.SalesPrice);
                salesLineDSD.LineAmount = salesLineDSD.calcLineAmountForced();

                if (salesLineDSD.RecId)
                {
                    salesLineDSD.SalesDeliverNow = _currentSalesLine.InventDeliverNow;
                    salesLineDSD.InventDeliverNow = salesLineDSD.SalesDeliverNow;
                    InventMovement::bufferSetRemainQty(salesLineDSD);

                    salesLineDSD.update();
                }
                else
                {       
                    salesLineDSD.createLine(false, false, false, true);
                }

                ttscommit;

                FormDataUtil::researchAndSetPos(_currentSalesLine, dsPos);
            }
            else
            {
                Global::warning(strFmt("@AVARUM:DSDNoPosCreatedItemNotFound", itemId));
            }
        }
    }
    catch
    {
        Global::error(strFmt("@AVARUM:DSDErrorCreatingPosition", itemId));
    }
}

/// <summary>
/// CoC | Modified for price recalculation
/// </summary>
void itemIdModified()
{
    salesLine salesLine;

    next itemIdModified();

    salesLine = this.cursor();
    salesLine.setCustomFields_AVA();

    this.refresh();
}

/// <summary>
/// CoC | Delete
/// </summary>
void  delete()
{
    next delete();

    this.research(true);
}

/// <summary>
/// CoC | Active
/// </summary>
/// <returns>Integer</returns>
int active()
{
    int ret;
    SalesLine salesLine;

    ret = next active();
    salesLine = this.cursor();

    this.allowEdit(!salesLine.AVARUMDSDPos);

    return ret;
}
